function SearchListHandler(response) {
    //console.log(response);
    var Category = ''
    $('#DineinCategory').html('');
    var html = '';
    $('#DineinItems').html('');
    $.each(response.categories, function (i, item) {
        Category += ' <div class="col-xs-6 col-md-3 DineinCategory" id = ' + item.Id + '><div class="thumbnail"><img src=' + item.ImageUrl + ' alt="..."><h3>' + item.CategoryDesc + '</h3></div></div>'
    });
    $('#DineinCategory').html(Category);
    $.each(response.items, function (i, item) {

        var itemdesc = item.ItemDesc.replace(/ /g, '');
        html += '<div class="col-xs-6 col-md-3 DineinItems" id=' + item.Id + ' data-Veriation=' + item.ItemVeriationId + ' data-CategoryId=' + item.CategoryId + ' data-SubCategoryId=' + item.SubCategoryId + ' data-RateId=' + item.RateId + ' data-Rate=' + item.Rate + ' data-ItemDesc=' + itemdesc + ' data-ItemSize=' + item.ItemSize + '><div class="thumbnail">' +
            '<img src=' + item.ImageURL + '><div class="caption"><h3>' + item.ItemDesc + '</h3>' +
            '<p>' + item.ItemSize + ' <br />Rs. ' + item.Rate + '</p></div></div></div>';
    });
    $('#DineinItems').html(html);
}
function SetHoldOrderListDineInHandler(response) {
    //console.log(response);
    var html = '';
    $('#tbl_Product tbody').html('');
    $.each(response, function (i, item) {
        html += '<tr>' +
            '<td hidden>' + item.ItemId + '</td>' +
            '<td hidden>' + item.ItemVeriationId + '</td>' +
            '<td hidden>' + item.CategoryId + '</td>' +
            '<td hidden>' + item.SubCategoryId + '</td>' +
            '<td hidden>' + item.ItemRateId + '</td>' +
            '<td>' + item.ItemDesc + '</td>' +
            /*'<td width="20px"></td>' +*/
            '<td width="20px"><button class="btn btn-primary MinusQtyinside">-</button></td>' +
            '<td width="20px" style="text-align:center">' + item.ItemQty + '</td>' +
            '<td class= width="40px"><button class="btn btn-primary AddQtyinside">+</button></td>' +
            //'<td width="40px"></td>' +
            '<td>' + item.Rate + '</td>' +
            '<td>' + item.Amount + '</td>' +
            '<td hidden>' + item.OrderMasterId + '</td>' +
            '<td hidden>' + item.OrderDetailId + '</td>' +
            '<td style="text-align: right;"><button class="btn btn-danger Delete"><i class="fa fa-trash"></i></button></td>' +
            '</tr>'
    });
    $('#tbl_Product tbody').append(html);
    calculateColumn(10);
    $('#ViewHoldOrder').modal('hide');
}
function ConvertJsonDateString(jsonDate) {
    var shortDate = null;
    if (jsonDate) {
        var regex = /-?\d+/;
        var matches = regex.exec(jsonDate);
        var dt = new Date(parseInt(matches[0]));
        var month = dt.getMonth() + 1;
        var monthString = month > 9 ? month : '0' + month;
        var day = dt.getDate();
        var dayString = day > 9 ? day : '0' + day;
        var year = dt.getFullYear();
        shortDate = year + '/' + monthString + '/' + dayString;
    }
    return shortDate;
};
function GetHoldOrderListDineInHandler(response) {
    var row = '';
    $('#tblHoldOrderDetails > tbody').html('');

    $.each(response.Data.masterJsons, function (i, item) {

        // Create a new Date object by parsing the number of milliseconds from the JSON string
        let orderDate = ConvertJsonDateString(item.OrderDate);

        row += '<tr class="OnholdJob"><td style= "display:none" class="HoldOrderId">' + item.OrderID + '</td><td style= "display:none" class="HoldTableId">' + item.TableId + '</td><td class="HoldOrderNo">' + item.JobRefNo + '</td><td class="HoldOrderDate">' + orderDate + '</td><td class="HoldOrderType">' + item.OrderType + '</td><td class="HoldTableNo">' + item.TableNo + '</td><td class="HoldOrderAmount">' + Math.round(item.OrderNetAmount) + '</td><td style= "display:none" class="HoldOrderTypeId">' + item.OrderTypeId + '</td></tr>'
        /*'<td class="text-right"><button class="btn btn-primary CategoryEdit"><i class="fa fa-edit"></i></button><button class="btn btn-danger Delete"><i class="fa fa-trash"></i></button></td></tr>'*/

    });
    $('#tblHoldOrderDetails > tbody').html(row);
}
