function SaveOrderDineInHandler(response, Order) {
    $('#Msg').html(response.Message);
    $('#tbl_Product tbody').html('');
    $('#dinein_NetAmount').val('');
    $('#ddlDineInTables').val(0);
    $("#select2-ddlDineInTables-container").text('SELECT');
    $('#ddlOrderType').val(0);
    $('#chkTakeaway').prop("checked", false);
    $('#ddlDineInTables').prop("disabled", false);
    $('#ddlOrderType').prop("disabled", false);
    $('#DineinDiscountAmount').val('');
    $('#DineinDiscount').val('0');
    $('#tbl_Product tfoot td').eq(5).text(0);
    $('#SavePopup').modal('show');

    if (response.HasError == false && (Order.OrderTypeId == 12 || Order.OrderTypeId == 13)) {
        var OrderTypeId = Order.OrderTypeId;
        var OrderId = response.OrderId;
        console.log(OrderTypeId);
        console.log(OrderId);
        InitializeDeliveryModal(OrderId, OrderTypeId);
    }

}
function calculateColumn(index) {
    //debugger;
    var total = 0;
    var NetAmount = 0;
    $('#tbl_Product tfoot td').eq(5).text('');
    $('.AdditionalAmount').text('');
    $('.AdditionalAmountVal').text('');
    $('#tbl_Product tbody tr').each(function () {
        var value = parseInt($('td', this).eq(index).text());
        if (!isNaN(value)) {
            total += value;
            NetAmount += value;
        }
    });


    if (adtamt != 0) {
        $('.AdditionalAmount').text('Additional Amount');
        $('.AdditionalAmountVal').text(adtamt);
        NetAmount = NetAmount + adtamt;
    }

    var DineinTax = $('#DineinTax').val();
    var dineinetaxValue = $('#DineinTax  option:selected').data('value')
    var DineinDiscount = $('#DineinDiscount option:selected').text();
    var DiscountValue = 0;
    var TaxValue = 0;
    var DineinDiscountVal = $('#DineinDiscount').val();
    if (DineinDiscountVal != 0) {
        DiscountValue = parseFloat(NetAmount) * parseFloat(DineinDiscount) / 100;
        $('#DineinDiscountAmount').val(DiscountValue);
        NetAmount = NetAmount - DiscountValue;
    }
    if (DineinTax != 0) {
        TaxValue = parseFloat(NetAmount) * parseFloat(dineinetaxValue) / 100;
        $('#DineinTaxAmount').val(TaxValue);
        NetAmount = NetAmount + TaxValue;
    }

    $('#tbl_Product tfoot td').eq(5).text(total + adtamt);
    $('#dinein_NetAmount').val(NetAmount);
}
