function BindTablesHandler(response) {
    let html = '<option value="0">Select Table</option>';

    $.each(response, function (i, item) {
        const statusDot = item.IsOccupied === 1 ? '🔴' : '🟢';
        const tableText = `${statusDot} ${item.TableNo}`;

        html += `<option value="${item.Id}">${tableText}</option>`;
    });

    $('#ddlDineInTables').html(html);
}

