function CheckDataExistsInTable(catId, SubCatId, ItemId, VeriationId, rate, addonid, option1, option2) {
    var C_CategoryId = catId;
    var C_SubCategoryId = SubCatId;
    var C_ItemId = ItemId;
    var C_ItemVeriationId = VeriationId;
    $("#tbl_Product tbody").find("tr").each(function () {
        var td1 = $(this).find("td:eq(2)").text();
        var td2 = $(this).find("td:eq(3)").text();
        var td3 = $(this).find("td:eq(0)").text();
        var td4 = $(this).find("td:eq(1)").text();
        var ExistingQty = $(this).find("td:eq(7)").text();
        var OrderMasterId = $(this).find("td:eq(11)").text();
        var ExistAddonid = $(this).find("td:eq(12)").text();
        var Existoption1id = $(this).find("td:eq(13)").text();
        var Existoption2id = $(this).find("td:eq(14)").text();
        var qty = 1;
        var Rate = rate;
        var TotalValue = 0;
        var TotalQty = 0;
        if ((C_CategoryId == td1) && (C_SubCategoryId == td2) && (C_ItemId == td3) && (C_ItemVeriationId == td4) && (OrderMasterId == "") && (addonid == ExistAddonid) && (option1 == Existoption1id) && (option2 == Existoption2id)) {
            flag = 1;

            TotalQty = parseInt(ExistingQty) + parseInt(qty);
            TotalValue = TotalQty * Rate;
            $(this).find("td:eq(7)").text(TotalQty);
            $(this).find("td:eq(10)").text(TotalValue);
            return false;
        }
        else {
            flag = 0;
        }
    });
}
