function BindtWaitersHandler(response) {
    //let waiterOptions = '<option value="">Select Waiter</option>';
    //const waitersMap = {};

    //$.each(response.Data, function (i, item) {
    //    const statusDot = item.IsLogin ? '🟢' : '🔴';
    //    const displayName = `${statusDot} ${item.WaiterName}`;

    //    waiterOptions += `<option
    //                        value="${item.Id}"
    //                        data-WaiterName="${item.WaiterName}"
    //                        data-IsLogin="${item.IsLogin}">
    //                        ${displayName}
    //                      </option>`;

    //    waitersMap[item.Id] = item;
    //});

    //$('#ddlWaiter').html(waiterOptions);
    const waitersMap = {};
    var waiter = '';
    waiter += "<option value=''>Select</option>";

    $.each(response.Data, function (i, item) {
        var statusDot = item.IsLogin ? '🟢' : '🔴';
        var disabled = item.IsLogin ? '' : 'disabled';

        waiter += '<option ' + disabled +
            ' data-WaiterId="' + item.Id +
            '" data-WaiterName="' + item.WaiterName +
            '" value="' + item.Id + '">' +
            statusDot + ' ' + item.WaiterName +
            '</option>';
        waitersMap[item.Id] = item;
    });

    $('#ddlWaiter').html(waiter)

    // On selection
    $('#ddlWaiter').off('change').on('change', function () {
        const selectedId = $(this).val();
        if (!selectedId) {
            $('#waiterStatus').html('');
            return;
        }

        const waiter = waitersMap[selectedId];

        if (!waiter.IsLogin) {
            $('#waiterStatus').html(''); 
            return;
        }

        let statusHtml = `
            <span class="waiter-dot" style="color:green; font-size: 16px;">●</span>
            <span class="waiter-name">${waiter.WaiterName}</span>
            <i class="fa fa-bell call-waiter"
               title="Call ${waiter.WaiterName}" 
               data-id="${waiter.Id}">
            </i>
        `;

        $('#waiterStatus').html(statusHtml);

    });

    //bell click
    $('#waiterStatus').off('click', '.call-waiter').on('click', '.call-waiter', function () {
        const waiterId = $(this).data('id');
        const payload = {
            Id: waiterId,
            DefaultClientId: DefaultClientId,
            IsOffline: 1
        };

        Common.Ajax('POST', url + 'CallWaiterFromWeb', JSON.stringify(payload), 'json', function (res) {
            alert("✅ Waiter has been called!");
            $('#ddlWaiter').val('');
            $('#waiterStatus').html('');
        });
    });
}


