function InitializeDeliveryModal(OrderId, OrderTypeId) {
    Common.Ajax('POST', url + 'GetAllDriverLists', JSON.stringify({ DefaultClientID: DefaultClientId }), 'json', function (response) {
        if (Array.isArray(response)) {
            $('#ddlRiders').empty();
            $('#ddlRiders').append(new Option('Select Rider', ''));

            response.forEach(function (rider) {
                $('#ddlRiders').append(new Option(rider.DriverName, rider.Id)); // Assuming 'DriverName' and 'Id' are correct keys
            });
        } else {
            alert('No riders found.');
        }
    }
    );
    $('#deliveryModal').modal('show');

    if (OrderTypeId == 12) {
        $('#txtOrderType').val('Delivery Order');
        $('#invoiceNoGroup').hide();
        $('#deliveryChargesGroup').show();
    } else if (OrderTypeId == 13) {
        $('#txtOrderType').val('FoodPanda Order');
        $('#invoiceNoGroup').show();
        $('#deliveryChargesGroup').hide();
    }

    $('#btnSaveDeliveryDetails').click(function () {
        var name = $('#txtName').val();
        var address = $('#txtAddress').val();
        var contactNumber = $('#txtContactNumber').val();
        var remarks = $('#txtRemarks').val();
        var deliveryCharges = $('#txtDeliveryCharges').val();
        var invoiceNo = $('#txtInvoiceNo').val();
        var riderId = $('#ddlRiders').val();

        if (OrderTypeId == 12) {
            if (!address || !contactNumber) {
                alert('Please fill in the required fields: Address or Contact Number.');
                return;
            }
        } if (OrderTypeId == 13 && !invoiceNo) {

            alert('Please insert Invoice No.');
            return;

        }

        var dataToSend = {
            DefaultClientId: DefaultClientId,
            OrderId: OrderId,
            CustomerName: name,
            Address: address,
            ContactNo: contactNumber,
            Remarks: remarks,
            DeliveryCharges: deliveryCharges,
            InvoiceNo: invoiceNo,
            RiderId: riderId,
            OrderType: OrderTypeId
        };

        console.log("Data to Send:", dataToSend);

        Common.Ajax('POST', url + 'InsertDeliveryDetails', JSON.stringify(dataToSend), 'json', function (response) {
            if (response.HasError === false) {
                $('#deliveryModal').modal('hide');
                console.log('Delivery details saved successfully!');
            } else {
                alert('Failed to save delivery details: ' + response.message);
            }
            $('#deliveryModal').modal('hide');
        }
        );

        $('#txtName').val('');
        $('#txtAddress').val('');
        $('#txtContactNumber').val('');
        $('#txtRemarks').val('');
        $('#txtDeliveryCharges').val('');
        $('#txtInvoiceNo').val('');
        $('#ddlRiders').val('');
        $('#deliveryModal').modal('hide');

    });
}
